void onion(ll a, ll b) {
    a = find(a); b = find(b);
    if (a == b) return;
    if (sz[a] < sz[b]) swap(a, b);
    pr[b] = a; sz[a] += sz[b];
}

void upd(ll c, ll p, ll x, ll id) {
    while (p < maxn) {
        fn[c][p].push({x, id}); p += (p & (-p));
    }
}

void nts(ll c, ll p, ll r, ll st) {
    ll wn = -1;
    for (; p > 0; p -= (p & (-p))) {
        while (!fn[c][p].empty()) {
            auto [rr, id] = fn[c][p].top();
            if (!df[id]) {
                fn[c][p].pop(); continue;
            }
            if (rr < r) break;
            wn = id; break;
        }
        if (wn != -1) {
            nd.pb({st, wn}); break;
        }
    }
}

